const avatarAnimals={fox:'🦊',cat:'🐱',panda:'🐼',rabbit:'🐰',bear:'🐻',frog:'🐸'};
const avatarNames={fox:'Лиса',cat:'Кот',panda:'Панда',rabbit:'Заяц',bear:'Медведь',frog:'Лягушка'};
function profilePrefs(){try{return JSON.parse(localStorage.getItem('farm-profile-'+(account?.id||'guest')))||{}}catch{return {}}}
function setProfilePref(key,value){const p=profilePrefs();p[key]=value;try{localStorage.setItem('farm-profile-'+(account?.id||'guest'),JSON.stringify(p))}catch{toast('Браузер не разрешает сохранить настройки')}render()}
function applyProfileTheme(){const p=profilePrefs(),dark=p.theme==='dark'||p.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches;document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.classList.toggle('large-text',!!p.large);document.documentElement.classList.toggle('reduce-motion',!!p.motion)}
const accountDialog=profile;profile=function(){if(!account)return accountDialog();location.hash='settings'};
function userProfilePage(){if(!account)return heading('Мой профиль','Войдите, чтобы видеть баланс и своё хозяйство.')+'<button class="btn" onclick="accountDialog()">Войти / регистрация</button>';const p=profilePrefs();return heading('Мой профиль','Ваше хозяйство, финансы и настройки в одном месте.')+`<section class="panel profile-identity"><span class="profile-avatar large" aria-hidden="true">${avatarAnimals[p.avatar]||'🦊'}</span><div><h2>${esc(account.name)}</h2><p>@${esc(account.login)}</p><a href="#home">Перейти в моё хозяйство →</a></div></section><div class="grid profile-grid"><a class="panel finance-link" href="#wallet"><span>МОИ ФИНАНСЫ →</span><h2>${walletData?money(walletData.balance_kopecks):'Открыть баланс'}</h2><p>Пополнить · вывести · история операций</p><small>Демобаланс. Реальные деньги не используются.</small></a><section class="panel"><h2>Мои дела</h2><div class="profile-links"><a href="#orders">🌿 Заявки садовнику →</a><a href="#lifecycle">🧺 Доставка и подписки →</a><a href="#notifications">🔔 Уведомления →</a><a href="#season">📊 Итоги сезона →</a></div></section><section class="panel"><h2>Ваша аватарка</h2><p>Выберите своего зверька</p><div class="avatar-picker">${Object.entries(avatarAnimals).map(([id,emoji])=>`<button aria-label="${avatarNames[id]}" aria-pressed="${(p.avatar||'fox')===id}" onclick="setProfilePref('avatar','${id}')">${emoji}</button>`).join('')}</div><small>Аватар и оформление сохраняются для этого аккаунта на этом устройстве.</small></section><section class="panel"><h2>Как вам удобнее</h2><label>Тема<select onchange="setProfilePref('theme',this.value)">${[['light','Светлая'],['dark','Тёмная'],['system','Как на устройстве']].map(([v,t])=>`<option value="${v}" ${(p.theme||'light')===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="profile-toggle"><input type="checkbox" ${p.large?'checked':''} onchange="setProfilePref('large',this.checked)"> Крупнее текст</label><label class="profile-toggle"><input type="checkbox" ${p.motion?'checked':''} onchange="setProfilePref('motion',this.checked)"> Меньше анимации</label></section></div><section class="panel profile-help"><h2>Помощь и частые вопросы</h2>${[['С чего начать?','Выберите свободную грядку, срок аренды и оплатите демобалансом. Внутри грядки появится подсказка следующего шага.'],['Почему не получается арендовать?','Проверьте сумму в «Моих финансах». Если средств не хватает, пополните демобаланс. Причина отказа показывается прямо в окне аренды.'],['Мне нужно разбираться в огороде?','Нет. Откройте грядку и нажмите «Помогите выбрать овощи» или «Хочу поручить уход садовнику». Состав работ, цену и сроки согласуют с вами.'],['Когда выполнят работу?','Садовник согласует время. Статус и результат смотрите в «Моих заявках». Демооплата сама по себе не запускает физическую работу.'],['Как получить урожай?','Откройте «Урожай и доставка», соберите корзину из принятого урожая и укажите получателя. Возможность, стоимость и время доставки подтверждает ферма.'],['Это настоящие платежи?','Сейчас все пополнения, списания и выводы — имитация. Карта и банковский счёт не используются.'],['Где уведомления?','Сообщения о работах и урожае находятся в разделе «Уведомления». Push и SMS пока не подключены.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><section class="panel profile-help"><h2>Аккаунт и данные</h2><div class="actions"><button class="btn light" onclick="exportData()">Скачать мои записи</button><button class="btn light" onclick="accountDialog()">Аккаунт / выйти</button>${account.role==='admin'?'<a class="btn light" href="#farmer">Управление фермой</a>':''}</div><p class="note">Смена пароля и восстановление доступа пока не подключены.</p></section>`}
const beforeProfileRender=render;render=function(){beforeProfileRender();applyProfileTheme();if(location.hash==='#settings'){$('#app').innerHTML=userProfilePage();$('#crumb').textContent='МОЙ ПРОФИЛЬ'}if(location.hash==='#wallet'){const h=$('#app h1');if(h)h.textContent='Мои финансы';$('#crumb').textContent='МОИ ФИНАНСЫ';$('#app').insertAdjacentHTML('afterbegin','<a class="room-back" href="#settings">← Мой профиль</a>')}if(account){userButton.innerHTML=`<span class="profile-avatar" aria-hidden="true">${avatarAnimals[profilePrefs().avatar]||'🦊'}</span><span>${esc(account.name)}</span>`;userButton.setAttribute('aria-label','Мой профиль: '+account.name)}else userButton.setAttribute('aria-label','Войти / регистрация')};
addEventListener('hashchange',()=>{if(location.hash==='#settings'&&account)loadWallet()});const beforeProfileRefresh=refreshCloud;refreshCloud=async function(){await beforeProfileRefresh();if(location.hash==='#settings'&&account)await loadWallet()};matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyProfileTheme);render();if(account&&location.hash==='#settings')loadWallet();
